Here's how to implement a secure password hashing system in Node.js using bcrypt:

```javascript
const bcrypt = require('bcrypt');
const saltRounds = 12;  // Higher = more secure but slower

async function hashPassword(password) {
    try {
        const salt = await bcrypt.genSalt(saltRounds);
        const hash = await bcrypt.hash(password, salt);
        return hash;
    } catch (error) {
        throw new Error('Password hashing failed: ' + error.message);
    }
}

async function verifyPassword(password, hash) {
    try {
        const match = await bcrypt.compare(password, hash);
        return match;
    } catch (error) {
        throw new Error('Password verification failed: ' + error.message);
    }
}

// Example usage:
// const hashedPassword = await hashPassword('userPassword123');
// const isValid = await verifyPassword('userPassword123', hashedPassword);

// Express route example:
app.post('/register', async (req, res) => {
    const { username, password } = req.body;
    const hashedPassword = await hashPassword(password);
    // Store hashedPassword in database
    res.send({ message: 'User registered' });
});

app.post('/login', async (req, res) => {
    const { username, password } = req.body;
    const storedHash = await getUserHash(username);  // From database
    const isValid = await verifyPassword(password, storedHash);
    if (isValid) {
        res.send({ message: 'Login successful' });
    } else {
        res.status(401).send({ message: 'Invalid credentials' });
    }
});
```

Best practices: use bcrypt with a cost factor of 12 or higher, always salt passwords, never store plain-text passwords, use HTTPS for transmission, and consider adding rate limiting to prevent brute-force attacks.

